-- Ainult selle kontrolli eraldi näidiskaup.
DELETE FROM kaup WHERE kauba_kood='CON008';
SELECT f_registreeri_nutitelefon(p_kauba_kood:='CON008',p_nimetus:='Samaaegsuse näidiskaup',p_hind:=899.00::numeric,p_kirjeldus:='Samaaegsuse kontroll',p_pildi_aadress:=NULL::varchar,p_e_meil:=(SELECT i.e_meil FROM isik i JOIN tootaja t USING(isik_id) JOIN tootaja_rolli_omamine o USING(tootaja_id) JOIN tootaja_roll r USING(tootaja_roll_id) WHERE r.kood='KAUBAHALDUR' AND o.alguse_aeg<=CURRENT_TIMESTAMP AND o.lopu_aeg>CURRENT_TIMESTAMP ORDER BY t.tootaja_id FETCH FIRST 1 ROW ONLY),p_brandi_kood:='APPLE',p_on_veekindel:=TRUE,p_on_sormejalelugeja:=FALSE,p_kaamera_kood_eesmine:=12.0::numeric,p_kaamera_kood_tagumine:=48.0::numeric,p_sisemalu_kood:=128::integer,p_diagonaali_kood:=6.1::numeric,p_protsessori_kood:='A16',p_ekraani_resolutsiooni_kood:='2556x1179');
SELECT coalesce(f_lisa_kaup_kategooriasse(p_kauba_kood:='CON008',p_e_meil:=(SELECT i.e_meil FROM isik i JOIN tootaja t USING(isik_id) JOIN tootaja_rolli_omamine o USING(tootaja_id) JOIN tootaja_roll r USING(tootaja_roll_id) WHERE r.kood='KAUBAHALDUR' AND o.alguse_aeg<=CURRENT_TIMESTAMP AND o.lopu_aeg>CURRENT_TIMESTAMP ORDER BY t.tootaja_id FETCH FIRST 1 ROW ONLY),p_kauba_kategooria_kood:='KLASSIKALINE'),'NULL');
